  var L = window.zybLang; if (!L || L.lang !== 'ar') return;
  // texts built by code around a translated part: the pattern translates the frame, the glossary the part
  var P = [
    [/^([\s\S]+) - open \/ hide$/, function (m, t) { return t(m[1]) + ' - إظهار / إخفاء'; }],
    [/^Supports \(evidence or control, not a certification\):\s*([\s\S]*)$/, function (m, t) { return 'يدعم (دليل أو ضابط، وليس شهادة): ' + t(m[1]); }],
    [/^Show every ([\s\S]+) dashboard$/, function (m, t) { return 'عرض كل لوحات ' + t(m[1]); }],
    [/^updated ([\s\S]+)$/i, function (m, t) { return 'آخر تحديث ' + t(m[1]); }],
    [/^not connected - update IT Asset Management \(([^)]+)\)\.$/, function (m) { return 'غير متصل - حدّث محرك إدارة أصول تقنية المعلومات (' + m[1] + ').'; }],
    [/^Could not read ([\s\S]+?): not connected$/, function (m, t) { return 'تعذّرت قراءة ' + t(m[1]) + ': غير متصل'; }],
    [/^([\s\S]+?) is not reachable \(not connected\)\.?$/, function (m, t) { return t(m[1]) + ' غير متاح (غير متصل).'; }],
    [/^([\s\S]+?) is not reachable: not connected$/, function (m, t) { return t(m[1]) + ' غير متاح: غير متصل'; }],
    [/^([\s\S]+?) not connected\.$/, function (m, t) { return t(m[1]) + ' غير متصل.'; }],
    [/^([\w.@-]+) · (Admin|Administrator|Operator|Viewer|Analyst)$/, function (m) { return m[1] + ' · ' + { Admin: 'مسؤول النظام', Administrator: 'مسؤول النظام', Operator: 'مشغّل', Viewer: 'مُطّلع', Analyst: 'محلل' }[m[2]]; }],
    [/^HTTP (\d+): not connected$/, function (m) { return 'HTTP ' + m[1] + ': غير متصل'; }],
    [/^read ([\d:. -]+)$/i, function (m) { return 'قُرئ ' + m[1]; }],
    [/^as of ([\s\S]+) UTC$/i, function (m) { return 'حتى ' + m[1] + ' بالتوقيت العالمي'; }],
    [/^(\d[\d,.]*) of (\d[\d,.]*)$/, function (m) { return m[1] + ' من ' + m[2]; }],
    [/^(\d[\d,.]*) selected$/, function (m) { return 'المحدد: ' + m[1]; }],
    // dashboard counts in the menu change whenever a page is added - one pattern, Arabic plural (3-10: لوحات, else لوحة)
    [/^(\d+) in this list$/, function (m) { return m[1] + ' في هذه القائمة'; }],
    [/^(\d+) shown$/, function (m) { return 'معروض: ' + m[1]; }],
    [/^(\d+) selected$/, function (m) { return 'محدد: ' + m[1]; }],
    [/^(\d+) dashboards?$/, function (m) { var n = +m[1]; return m[1] + (n >= 3 && n <= 10 ? ' لوحات' : ' لوحة'); }],
    [/^All (\d+) →$/, function (m) { return 'الكل ' + m[1] + ' →'; }],
    [/^(\d+) days?$/, function (m) { return m[1] + ' يوم'; }],
    [/^(\d+) hours?$/, function (m) { return m[1] + ' ساعة'; }],
    [/^(\d+) min(?:ute)?s?$/, function (m) { return m[1] + ' دقيقة'; }]
  ];
  L.extend({ terms: T, patterns: P });
  // framework citations: "PDPL Art. 19" reads "PDPL المادة 19" (the keys stay as they are - they are ids)
